def run_agent(user_msg, call_model, handlers, max_steps=8):
    messages = [{"role": "user", "content": user_msg}]
    for _ in range(max_steps):
        resp = call_model(messages)
        messages.append({"role": "assistant", "content": resp["content"]})
        if resp["stop_reason"] != "tool_use":
            return "".join(b["text"] for b in resp["content"] if b["type"] == "text")
        results = []
        for block in resp["content"]:
            if block["type"] != "tool_use":
                continue
            res = {"type": "tool_result", "tool_use_id": block["id"]}
            fn = handlers.get(block["name"])
            if fn is None:
                res.update(content=f"unknown tool {block['name']}", is_error=True)
            else:
                try:
                    res["content"] = str(fn(**block["input"]))
                except Exception as e:  # report, don't crash the loop
                    res.update(content=f"{type(e).__name__}: {e}", is_error=True)
            results.append(res)
        messages.append({"role": "user", "content": results})  # all results, one message
    raise RuntimeError(f"no final answer after {max_steps} steps")


def mock_model(messages):
    """Fake model: asks for two cities in parallel, then answers."""
    last = messages[-1]["content"]
    if isinstance(last, str):
        return {"stop_reason": "tool_use", "content": [
            {"type": "tool_use", "id": "t1", "name": "weather", "input": {"city": "Haifa"}},
            {"type": "tool_use", "id": "t2", "name": "weather", "input": {"city": "Eilat"}}]}
    text = "; ".join(r["content"] for r in last)
    return {"stop_reason": "end_turn", "content": [{"type": "text", "text": text}]}


def weather(city):
    if city == "Eilat":
        raise TimeoutError("service timeout")
    return f"{city}: 22C"


if __name__ == "__main__":
    print(run_agent("weather?", mock_model, {"weather": weather}))

