import json


def run_guarded(user_msg, call_model, handlers, destructive, approve,
                max_steps=10, max_repeats=2):
    messages = [{"role": "user", "content": user_msg}]
    seen, log = {}, []
    for _ in range(max_steps):
        resp = call_model(messages)
        messages.append({"role": "assistant", "content": resp["content"]})
        if resp["stop_reason"] != "tool_use":
            text = "".join(b["text"] for b in resp["content"] if b["type"] == "text")
            return text, log
        results = []
        for blk in (b for b in resp["content"] if b["type"] == "tool_use"):
            name, args = blk["name"], blk["input"]
            key = (name, json.dumps(args, sort_keys=True))
            seen[key] = seen.get(key, 0) + 1
            if name not in handlers:
                status, out = "error", f"unknown tool {name}"
            elif seen[key] > max_repeats:
                status, out = "error", "repeated identical call blocked; change approach"
            elif name in destructive and not approve(name, args):
                status, out = "error", "denied by user; do not retry without a new request"
            else:
                try:
                    status, out = "ok", str(handlers[name](**args))
                except Exception as e:
                    status, out = "error", f"{type(e).__name__}: {e}"
            log.append({"tool": name, "input": args, "status": status})
            res = {"type": "tool_result", "tool_use_id": blk["id"], "content": out}
            if status == "error":
                res["is_error"] = True
            results.append(res)
        messages.append({"role": "user", "content": results})
    raise RuntimeError("step budget exhausted")


def mock_model(messages):
    turn = sum(1 for m in messages if m["role"] == "assistant")
    if turn == 0:
        return {"stop_reason": "tool_use", "content": [
            {"type": "tool_use", "id": "a", "name": "read", "input": {"p": "/x"}},
            {"type": "tool_use", "id": "b", "name": "delete", "input": {"p": "/y"}}]}
    errs = [r for r in messages[-1]["content"] if r.get("is_error")]
    return {"stop_reason": "end_turn",
            "content": [{"type": "text", "text": f"done, {len(errs)} blocked"}]}


if __name__ == "__main__":
    h = {"read": lambda p: "data", "delete": lambda p: "deleted"}
    print(run_guarded("clean", mock_model, h, {"delete"}, lambda n, a: False))
